78	/**
79	 * Ensures `rg` is downloaded, or throws.
80	 */
81	export async function ensureRgPath(): Promise<string> {
82	  const downloadedPath = await ensureRipgrepAvailable();
83	  if (downloadedPath) {
84	    return downloadedPath;
85	  }
86	  throw new Error('Cannot use ripgrep.');
87	}
